"use client"

import {
  type Cell,
  type ColumnDef,
  type ColumnFiltersState,
  type OnChangeFn,
  type Row,
  type RowData,
  type SortingState,
  type Table as TanTable,
  type VisibilityState,
  flexRender,
  getCoreRowModel,
  getFacetedRowModel,
  getFacetedUniqueValues,
  getFilteredRowModel,
  getSortedRowModel,
  useReactTable,
} from "@tanstack/react-table"
import { useWindowVirtualizer } from "@tanstack/react-virtual"
import Link from "next/link"
import { usePathname, useRouter } from "next/navigation"
import * as React from "react"

import { type ListPosition, listCacheKey, saveList, takeList } from "@/components/data-table/list-cache"
import { useUrlListQuery } from "@/components/data-table/list-query"
import {
  type FetchItem,
  type FetchPage,
  type ItemMark,
  type ListQuery,
  applyItemUpdate,
  queryKey,
  useInfiniteList,
} from "@/components/data-table/list-source"
import { subscribeItemUpdates } from "@/components/data-table/list-updates"
import { StatusBadge } from "@/components/status-badge"
import { Button } from "@/components/ui/button"
import { Skeleton } from "@/components/ui/skeleton"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { mergeLabels } from "@/lib/labels"
import { type RoutedDialogEventDetail, routedDialogEvent, routedTransitionName } from "@/lib/routed"
import { cn } from "@/lib/utils"

export type Density = "comfortable" | "compact"

/** Where a column's cell goes in a card on the Celular (below `md`). Columns without a slot stay out of the card. */
export type CardSlot = "title" | "subtitle" | "status" | "value"

declare module "@tanstack/react-table" {
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  interface ColumnMeta<TData extends RowData, TValue> {
    mobile?: CardSlot
    /** Plain-text name of the column for menus (Sort by, column visibility) when `header` is not a string. */
    title?: string
  }
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  interface TableMeta<TData extends RowData> {
    /** Every record that matches the query, loaded or not. Set by `DataTable`. */
    total?: number
  }
}

const CardCellContext = React.createContext(false)

/** True while a cell renders inside a card, where nested interactive elements are not allowed. */
export function useIsCardCell() {
  return React.useContext(CardCellContext)
}

export type DataTableLabels = {
  noResults: string
  /** Count on top of the list, e.g. "50 of 1,284 results": `loaded` records are on screen out of `total`. */
  total: (loaded: number, total: number) => string
  /** Selection count, e.g. "3 selected". Only loaded rows can be selected. */
  selected: (selected: number) => string
  /** Shown at the end of the list when a page fails to load. */
  loadError: string
  retry: string
  /** Marks on records changed since their page loaded (see `markItemChanged`). */
  markNew: string
  markStale: string
  markDeleted: string
}

const count = new Intl.NumberFormat("en-US")

export const defaultDataTableLabels: DataTableLabels = {
  noResults: "No results.",
  total: (loaded, total) => `${count.format(loaded)} of ${count.format(total)} ${total === 1 ? "result" : "results"}`,
  selected: (selected) => `${count.format(selected)} selected`,
  loadError: "Couldn't load more.",
  retry: "Retry",
  markNew: "New",
  markStale: "Doesn't match filters",
  markDeleted: "Deleted",
}

type CommonProps<TData> = {
  columns: ColumnDef<TData>[]
  /** Accessible name for the table. */
  label: string
  toolbar?: (table: TanTable<TData>, density: Density, setDensity: (d: Density) => void) => React.ReactNode
  /**
   * Makes each record a link, for a Dialog roteado: the card is the link, and the row is clickable.
   * The dialog zooms out of the row or card whose href it was opened at.
   */
  getRowHref?: (row: TData) => string
  /** For lists without routes; `getRowHref` wins when both are given. */
  onRowClick?: (row: TData) => void
  /** Stable id of a record. Defaults to its `id` field, else its index. */
  getRowId?: (row: TData) => string
  emptyState?: React.ReactNode
  /** Partial overrides, merged over `defaultDataTableLabels`. */
  labels?: Partial<DataTableLabels>
}

type LocalProps<TData> = {
  /** Every record, filtered and sorted in the browser. For small lists. */
  data: TData[]
  fetchPage?: never
}

type ServerProps<TData> = {
  data?: never
  /** Loads one page at a time by cursor; search, filters and sort run on the server. */
  fetchPage: FetchPage<TData>
  /** Name shared with `markItemChanged(resource, id)`, e.g. `"orders"`. */
  resource?: string
  /** Fetches one record again after `markItemChanged`, to update it in place. */
  fetchItem?: FetchItem<TData>
}

export type DataTableProps<TData> = CommonProps<TData> & (LocalProps<TData> | ServerProps<TData>)

const defaultRowId = <TData,>(row: TData, index: number) => {
  const id = (row as { id?: unknown }).id
  return id == null ? String(index) : String(id)
}

/** The query as TanStack state, and back. */
function useQueryTableState(query: ListQuery, setQuery: (update: (q: ListQuery) => ListQuery) => void) {
  const sorting = React.useMemo<SortingState>(() => (query.sort ? [query.sort] : []), [query.sort])
  const columnFilters = React.useMemo<ColumnFiltersState>(
    () => Object.entries(query.filters).map(([id, value]) => ({ id, value })),
    [query.filters],
  )
  const onSortingChange: OnChangeFn<SortingState> = (updater) =>
    setQuery((q) => {
      const next = typeof updater === "function" ? updater(q.sort ? [q.sort] : []) : updater
      return { ...q, sort: next[0] ? { id: next[0].id, desc: next[0].desc } : undefined }
    })
  const onColumnFiltersChange: OnChangeFn<ColumnFiltersState> = (updater) =>
    setQuery((q) => {
      const current = Object.entries(q.filters).map(([id, value]) => ({ id, value }))
      const next = typeof updater === "function" ? updater(current) : updater
      const filters: Record<string, string[]> = {}
      for (const f of next) {
        const value = f.value as string[] | undefined
        if (value?.length) filters[f.id] = value
      }
      return { ...q, filters }
    })
  const onGlobalFilterChange: OnChangeFn<string> = (updater) =>
    setQuery((q) => {
      const next = typeof updater === "function" ? updater(q.q ?? "") : updater
      return { ...q, q: next || undefined }
    })
  return { sorting, columnFilters, onSortingChange, onColumnFiltersChange, onGlobalFilterChange }
}

const desktopQuery = "(min-width: 768px)"

/** `null` until hydrated: the server renders both forms and CSS hides one. */
function useIsDesktop() {
  return React.useSyncExternalStore(
    (onChange) => {
      const m = window.matchMedia(desktopQuery)
      m.addEventListener("change", onChange)
      return () => m.removeEventListener("change", onChange)
    },
    () => window.matchMedia(desktopQuery).matches,
    () => null,
  )
}

/** Rows rendered before hydration, when the visible form is not known yet. */
const unhydratedRows = 20

/** Window-scrolled virtual rows for the element in `ref`. `on: null` renders the first rows without virtualizing. */
function useVirtualRows(
  ref: React.RefObject<HTMLElement | null>,
  count: number,
  estimate: number,
  on: boolean | null,
  getItemKey: (index: number) => string,
) {
  const [margin, setMargin] = React.useState(0)
  React.useLayoutEffect(() => {
    const el = ref.current
    if (!el || !on) return
    const update = () => {
      const top = el.getBoundingClientRect().top + window.scrollY
      setMargin((prev) => (Math.abs(prev - top) > 0.5 ? top : prev))
    }
    update()
    const observer = new ResizeObserver(update)
    observer.observe(document.body)
    return () => observer.disconnect()
  }, [ref, on])

  const virtualizer = useWindowVirtualizer({
    count,
    estimateSize: () => estimate,
    overscan: 8,
    scrollMargin: margin,
    enabled: !!on,
    getItemKey,
  })

  if (on === null) {
    const items = Array.from({ length: Math.min(count, unhydratedRows) }, (_, index) => ({ index }))
    return { items, before: 0, after: 0, last: -1, measure: undefined, scrollToIndex: undefined }
  }
  const items = on ? virtualizer.getVirtualItems() : []
  const before = items.length ? items[0].start - margin : 0
  const after = items.length ? virtualizer.getTotalSize() - (items[items.length - 1].end - margin) : 0
  return {
    items,
    before: Math.max(0, before),
    after: Math.max(0, after),
    last: items.length ? items[items.length - 1].index : -1,
    measure: virtualizer.measureElement,
    scrollToIndex: (index: number, align: "auto" | "start" = "auto") => virtualizer.scrollToIndex(index, { align }),
  }
}

export function DataTable<TData>(props: DataTableProps<TData>) {
  const { columns, label, toolbar, getRowHref, onRowClick, getRowId, emptyState, labels } = props
  const t = mergeLabels(defaultDataTableLabels, labels)
  const server = !!props.fetchPage
  const columnIds = React.useMemo(
    () => columns.map((c) => c.id ?? (c as { accessorKey?: string }).accessorKey).filter((id): id is string => !!id),
    [columns],
  )
  const [query, setQuery] = useUrlListQuery(columnIds)
  const pathname = usePathname()
  const [listPath] = React.useState(pathname)
  // Coming back to a list left a moment ago (the sidebar, a link): its pages, marks and position.
  const [restored] = React.useState(() => (server ? takeList<TData>(listCacheKey(listPath, query)) : undefined))
  const list = useInfiniteList(props.fetchPage, query, restored?.state ?? undefined, (key) => {
    // The same list shown again for another query (the router reuses a hidden page): from the cache if kept.
    const entry = takeList<TData>(`${listPath}?${key}`)
    if (entry?.position) queueMicrotask(() => setPending(entry.position))
    return entry?.state
  })

  // A record changed elsewhere (a dialog, an action): fetch it again and update it in place.
  const resource = props.fetchPage ? props.resource : undefined
  const fetchItem = props.fetchPage ? props.fetchItem : undefined
  const queryRef = React.useRef(query)
  React.useLayoutEffect(() => {
    queryRef.current = query
  })
  const { setState: setListState } = list
  React.useEffect(() => {
    if (!resource || !fetchItem) return
    const idOf = (item: TData) => (getRowId ? getRowId(item) : defaultRowId(item, -1))
    return subscribeItemUpdates(async (updates) => {
      for (const update of updates) {
        if (update.resource !== resource) continue
        const result = await fetchItem(update.id, queryRef.current).catch(() => undefined)
        if (result === undefined) continue
        setListState((s) => applyItemUpdate(s, update, result, idOf))
      }
    })
  }, [resource, fetchItem, getRowId, setListState])

  const [columnVisibility, setColumnVisibility] = React.useState<VisibilityState>({})
  const [rowSelection, setRowSelection] = React.useState({})
  const [density, setDensity] = React.useState<Density>("comfortable")
  const tableState = useQueryTableState(query, setQuery)

  // Facet counts come from the server; read through a ref so TanStack's cached getters see fresh values.
  const facetsRef = React.useRef(list.facets)
  React.useLayoutEffect(() => {
    facetsRef.current = list.facets
  })

  const data = server ? list.items : (props.data ?? [])
  const table = useReactTable({
    data,
    columns,
    state: {
      sorting: tableState.sorting,
      columnFilters: tableState.columnFilters,
      globalFilter: query.q ?? "",
      columnVisibility,
      rowSelection,
    },
    getRowId: getRowId ? (row) => getRowId(row) : defaultRowId,
    enableRowSelection: true,
    manualFiltering: server,
    manualSorting: server,
    onSortingChange: tableState.onSortingChange,
    onColumnFiltersChange: tableState.onColumnFiltersChange,
    onGlobalFilterChange: tableState.onGlobalFilterChange,
    onColumnVisibilityChange: setColumnVisibility,
    onRowSelectionChange: setRowSelection,
    getCoreRowModel: getCoreRowModel(),
    getFilteredRowModel: server ? undefined : getFilteredRowModel(),
    getSortedRowModel: server ? undefined : getSortedRowModel(),
    getFacetedRowModel: server ? undefined : getFacetedRowModel(),
    getFacetedUniqueValues: server
      ? (_table, columnId) => () => new Map(Object.entries(facetsRef.current?.[columnId] ?? {}))
      : getFacetedUniqueValues(),
    meta: { total: server ? list.total : undefined },
  })

  const rows = table.getRowModel().rows
  const loaded = rows.length
  const total = server ? list.total : loaded
  const selected = Object.keys(rowSelection).length
  const status = server ? list.status : "idle"

  const visibleColumns = table.getVisibleLeafColumns()
  const hasSlots = visibleColumns.some((c) => c.columnDef.meta?.mobile)
  // Without any slot, the first visible column that holds data becomes the title.
  const fallbackTitleId = hasSlots ? undefined : visibleColumns.find((c) => c.accessorFn)?.id

  React.useEffect(() => {
    if (process.env.NODE_ENV !== "production" && !hasSlots) {
      console.warn(
        `DataTable "${label}": no column sets meta.mobile, so the first column with data is the card title. Set meta.mobile to "title" | "subtitle" | "status" | "value".`,
      )
    }
  }, [hasSlots, label])

  const titleColumnId = visibleColumns.find((c) => c.columnDef.meta?.mobile === "title")?.id ?? fallbackTitleId
  const marks = server ? list.marks : {}
  const markLabel: Record<ItemMark, string> = { new: t.markNew, stale: t.markStale, deleted: t.markDeleted }

  const slotOf = (cell: Cell<TData, unknown>): CardSlot | undefined =>
    cell.column.columnDef.meta?.mobile ?? (cell.column.id === fallbackTitleId ? "title" : undefined)

  const isDesktop = useIsDesktop()
  const cardsRef = React.useRef<HTMLUListElement>(null)
  const bodyRef = React.useRef<HTMLTableSectionElement>(null)
  const regionRef = React.useRef<HTMLDivElement>(null)
  const rowKey = React.useCallback((index: number) => rows[index]?.id ?? String(index), [rows])
  const rowHeight = density === "compact" ? 33 : 41
  const cards = useVirtualRows(cardsRef, loaded, 72, isDesktop === null ? null : !isDesktop, rowKey)
  const tableRows = useVirtualRows(bodyRef, loaded, rowHeight, isDesktop === null ? null : isDesktop, rowKey)

  // Ask for the next page when the rows on screen get within one screen of the end.
  const visible = isDesktop ? tableRows : cards
  const { fetchNext } = list
  React.useEffect(() => {
    if (!server || visible.last < 0) return
    const screen = Math.ceil(window.innerHeight / (isDesktop ? rowHeight : 72))
    if (visible.last >= loaded - 1 - screen) fetchNext()
  }, [server, visible.last, loaded, isDesktop, rowHeight, fetchNext, list.status])

  // A new query starts at the top of the list.
  const shownKey = list.key
  const previousKey = React.useRef(shownKey)
  React.useEffect(() => {
    if (previousKey.current === shownKey) return
    const hadData = previousKey.current !== ""
    previousKey.current = shownKey
    const region = regionRef.current
    if (!hadData || !region) return
    const top = region.getBoundingClientRect().top + window.scrollY - 16
    if (window.scrollY > top) window.scrollTo({ top })
  }, [shownKey])

  // The record a Dialog roteado was opened from gives up its transition name to the dialog while it is open.
  const router = useRouter()
  const [origin, setOrigin] = React.useState<string | null>(null)
  if (pathname === listPath && origin !== null) setOrigin(null)
  if (pathname !== listPath && origin === null) setOrigin(pathname)

  // On close, the record it came from gets the focus back (scrolled into view if needed).
  const rowsRef = React.useRef(rows)
  const visibleRef = React.useRef(visible)
  React.useLayoutEffect(() => {
    rowsRef.current = rows
    visibleRef.current = visible
  })
  React.useEffect(() => {
    if (!getRowHref) return
    const onDialog = (e: Event) => {
      const { type, origin: href } = (e as CustomEvent<RoutedDialogEventDetail>).detail
      if (type !== "close") return
      const index = rowsRef.current.findIndex((r) => getRowHref(r.original) === href)
      if (index < 0) return
      const container = window.matchMedia(desktopQuery).matches ? bodyRef.current : cardsRef.current
      const focus = () => {
        const link = Array.from(container?.querySelectorAll<HTMLElement>("a[href]") ?? []).find(
          (a) => a.getAttribute("href") === href,
        )
        if (!link) return false
        link.focus({ preventScroll: true })
        const box = link.getBoundingClientRect()
        if (box.top < 0 || box.bottom > window.innerHeight) link.scrollIntoView({ block: "center" })
        return true
      }
      if (focus()) return
      visibleRef.current.scrollToIndex?.(index)
      requestAnimationFrame(() => requestAnimationFrame(focus))
    }
    window.addEventListener(routedDialogEvent, onDialog)
    return () => window.removeEventListener(routedDialogEvent, onDialog)
  }, [getRowHref])

  const hrefOf = (row: Row<TData>) => (getRowHref ? getRowHref(row.original) : undefined)
  const activate = (row: Row<TData>) => {
    const href = hrefOf(row)
    if (href) router.push(href)
    else onRowClick?.(row.original)
  }
  const clickable = !!getRowHref || !!onRowClick

  // Where the list is on screen, kept up to date while scrolling, to restore it later.
  const position = React.useRef<ListPosition | null>(restored?.position ?? null)
  React.useEffect(() => {
    if (!server || isDesktop === null) return
    const container = isDesktop ? bodyRef.current : cardsRef.current
    let frame = 0
    const update = () => {
      for (const el of container?.querySelectorAll<HTMLElement>(":scope > [data-index]") ?? []) {
        const box = el.getBoundingClientRect()
        if (box.bottom > 0) {
          position.current = { index: Number(el.dataset.index), offset: box.top }
          return
        }
      }
    }
    const onScroll = () => {
      cancelAnimationFrame(frame)
      frame = requestAnimationFrame(update)
    }
    window.addEventListener("scroll", onScroll, { passive: true })
    return () => {
      cancelAnimationFrame(frame)
      window.removeEventListener("scroll", onScroll)
    }
  }, [server, isDesktop])

  // Leaving the screen: into the session cache, under the query it shows.
  const saveRef = React.useRef<() => void>(() => {})
  const hiddenKey = React.useRef<string | null>(null)
  React.useLayoutEffect(() => {
    saveRef.current = () => {
      hiddenKey.current = list.key
      if (!server || list.status === "loading" || !list.key) return
      const { items, marks, nextCursor, total, facets, key } = list
      saveList<TData>(`${listPath}?${key}`, {
        state: { items, marks, nextCursor, total, facets, key, status: "idle" },
        position: position.current,
        resource,
        query,
        fetchItem,
        idOf: (item) => (getRowId ? getRowId(item) : defaultRowId(item, -1)),
      })
    }
  })
  // The router can keep a page it leaves hidden, with its state, and show it again: the effects run again
  // but nothing mounts. Then the list takes its cache entry back like a fresh mount would, or starts over
  // when the entry is gone (too old, or one of more than five lists).
  const shown = React.useRef(false)
  const showAgainRef = React.useRef<() => void>(() => {})
  React.useLayoutEffect(() => {
    showAgainRef.current = () => {
      // Shown again for another query: the change of query already took it from the cache, or fetches it.
      if (!server || hiddenKey.current !== queryKey(query)) return
      const entry = takeList<TData>(listCacheKey(listPath, query))
      if (entry?.state) {
        setListState(entry.state)
        setPending(entry.position)
      } else if (entry?.position) {
        list.reload()
        setPending(entry.position)
      } else {
        list.reload()
        window.scrollTo({ top: 0 })
      }
    }
  })
  React.useEffect(() => {
    if (shown.current) queueMicrotask(() => showAgainRef.current())
    shown.current = true
    return () => saveRef.current()
  }, [])

  // Back from the cache: scroll to the record that was first on screen, loading pages up to it if needed.
  const [pending, setPending] = React.useState<ListPosition | null>(restored?.position ?? null)
  React.useEffect(() => {
    if (!pending || isDesktop === null || !server) return
    if (loaded <= pending.index) {
      if (list.status === "idle" && list.nextCursor) fetchNext()
      else if (list.status === "idle") queueMicrotask(() => setPending(null))
      return
    }
    if (!visibleRef.current.scrollToIndex) return
    // The router scrolls a new page to the top right after it mounts: restore after that.
    let correct: ReturnType<typeof setTimeout> | undefined
    const start = setTimeout(() => {
      visibleRef.current.scrollToIndex?.(pending.index, "start")
      // Once the virtualizer has placed it, put the record exactly where it was on screen.
      correct = setTimeout(() => {
        const container = isDesktop ? bodyRef.current : cardsRef.current
        const el = container?.querySelector<HTMLElement>(`:scope > [data-index="${pending.index}"]`)
        if (el) window.scrollBy(0, el.getBoundingClientRect().top - pending.offset)
        setPending(null)
      }, 120)
    }, 80)
    return () => {
      clearTimeout(start)
      clearTimeout(correct)
    }
  }, [pending, isDesktop, server, loaded, list.status, list.nextCursor, fetchNext])

  const busy = status === "refreshing" || status === "loading"
  const tail =
    status === "loading" || status === "loading-more"
      ? "skeleton"
      : status === "error"
        ? "error"
        : !loaded
          ? "empty"
          : null
  const skeletonRows = status === "loading" ? 8 : 3
  const retry = (
    <span className="flex flex-wrap items-center justify-center gap-3">
      {t.loadError}
      <Button variant="outline" onClick={list.retry}>
        {t.retry}
      </Button>
    </span>
  )

  return (
    <div ref={regionRef} role="region" aria-label={label} className="flex flex-col gap-3">
      {toolbar?.(table, density, setDensity)}
      <p role="status" className="min-h-5 text-muted-foreground tabular-nums">
        {status === "loading" ? null : (
          <>
            {t.total(loaded, total)}
            {selected > 0 ? ` · ${t.selected(selected)}` : null}
          </>
        )}
      </p>
      <ul
        ref={cardsRef}
        aria-label={label}
        aria-busy={busy || undefined}
        className={cn(
          "flex flex-col overflow-hidden rounded-lg border bg-card transition-opacity md:hidden",
          status === "refreshing" && "opacity-60",
        )}
        style={{ paddingTop: cards.before, paddingBottom: cards.after }}
      >
        {cards.items.map(({ index }) => {
          const row = rows[index]
          if (!row) return null
          return (
            <DataCard
              key={row.id}
              index={index}
              setSize={total}
              measure={cards.measure}
              cells={row.getVisibleCells()}
              slotOf={slotOf}
              mark={marks[row.id]}
              markLabel={markLabel}
              href={marks[row.id] === "deleted" ? undefined : hrefOf(row)}
              isOrigin={hrefOf(row) === origin}
              onClick={onRowClick && marks[row.id] !== "deleted" ? () => onRowClick(row.original) : undefined}
            />
          )
        })}
        {tail === "skeleton"
          ? Array.from({ length: skeletonRows }, (_, i) => (
              <li key={`skeleton-${i}`} aria-hidden className="flex flex-col gap-2 border-b px-4 py-3 last:border-b-0">
                <Skeleton className="h-4 w-2/3" />
                <Skeleton className="h-4 w-1/3" />
              </li>
            ))
          : null}
        {tail === "error" ? <li className="flex min-h-24 items-center justify-center p-4 text-center">{retry}</li> : null}
        {tail === "empty" ? (
          <li className="flex h-48 items-center justify-center text-center text-muted-foreground">
            {emptyState ?? t.noResults}
          </li>
        ) : null}
      </ul>
      <div className="hidden overflow-hidden rounded-lg border bg-card md:block">
        <Table
          aria-label={label}
          aria-rowcount={total + 1}
          aria-busy={busy || undefined}
          data-density={density}
          className={cn("group/table transition-opacity", status === "refreshing" && "opacity-60")}
        >
          <TableHeader className="bg-muted/50">
            {table.getHeaderGroups().map((hg) => (
              <TableRow key={hg.id} aria-rowindex={1} className="hover:bg-transparent">
                {hg.headers.map((header) => (
                  <TableHead
                    key={header.id}
                    style={{ width: header.column.columnDef.size !== 150 ? header.column.columnDef.size : undefined }}
                    aria-sort={
                      header.column.getIsSorted() === "asc"
                        ? "ascending"
                        : header.column.getIsSorted() === "desc"
                          ? "descending"
                          : undefined
                    }
                    className="h-9 text-xs font-medium text-muted-foreground"
                  >
                    {header.isPlaceholder ? null : flexRender(header.column.columnDef.header, header.getContext())}
                  </TableHead>
                ))}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody ref={bodyRef}>
            {tableRows.before > 0 ? <Spacer height={tableRows.before} colSpan={visibleColumns.length} /> : null}
            {tableRows.items.map(({ index }) => {
              const row = rows[index]
              if (!row) return null
              return (
                <DataRow
                  key={row.id}
                  row={row}
                  index={index}
                  measure={tableRows.measure}
                  href={hrefOf(row)}
                  isOrigin={hrefOf(row) === origin}
                  mark={marks[row.id]}
                  markLabel={markLabel}
                  titleColumnId={titleColumnId}
                  onClick={clickable && marks[row.id] !== "deleted" ? () => activate(row) : undefined}
                />
              )
            })}
            {tableRows.after > 0 ? <Spacer height={tableRows.after} colSpan={visibleColumns.length} /> : null}
            {tail === "skeleton"
              ? Array.from({ length: skeletonRows }, (_, i) => (
                  <TableRow key={`skeleton-${i}`} aria-hidden className="hover:bg-transparent">
                    <TableCell colSpan={visibleColumns.length} className="h-10">
                      <Skeleton className="h-4 w-full" />
                    </TableCell>
                  </TableRow>
                ))
              : null}
            {tail === "error" ? (
              <TableRow className="hover:bg-transparent">
                <TableCell colSpan={visibleColumns.length} className="h-24 text-center">
                  {retry}
                </TableCell>
              </TableRow>
            ) : null}
            {tail === "empty" ? (
              <TableRow className="hover:bg-transparent">
                <TableCell colSpan={visibleColumns.length} className="h-48 text-center text-muted-foreground">
                  {emptyState ?? t.noResults}
                </TableCell>
              </TableRow>
            ) : null}
          </TableBody>
        </Table>
      </div>
    </div>
  )
}

function Spacer({ height, colSpan }: { height: number; colSpan: number }) {
  return (
    <tr aria-hidden style={{ height }}>
      <td colSpan={colSpan} className="p-0" />
    </tr>
  )
}

/**
 * Wraps a row or card in a View Transition named after its href. While the dialog opened from it is
 * on screen the wrapper is gone: React pairs a removed name with an added one, which is the zoom.
 */
function Zoom({ href, isOrigin, children }: { href?: string; isOrigin: boolean; children: React.ReactElement }) {
  if (!href || isOrigin) return children
  return (
    <React.ViewTransition name={routedTransitionName(href)} share="routed-zoom" default="none">
      {children}
    </React.ViewTransition>
  )
}

// Links, checkboxes and menus inside a row do their own thing.
const interactive = "a, button, input, select, textarea, label, [role='checkbox'], [role='menuitem']"

const markTone = { new: "info", stale: "warning", deleted: "danger" } as const

/** The mark of a changed record, next to its title. */
function RowMark({ mark, label }: { mark: ItemMark; label: Record<ItemMark, string> }) {
  return (
    <span data-slot="row-mark" className="inline-block no-underline">
      <StatusBadge tone={markTone[mark]}>{label[mark]}</StatusBadge>
    </span>
  )
}

const markRow: Record<ItemMark, string> = {
  new: "",
  stale: "bg-muted/60",
  deleted: "bg-muted/60 text-muted-foreground line-through",
}

function DataRow<TData>({
  row,
  index,
  measure,
  href,
  isOrigin,
  mark,
  markLabel,
  titleColumnId,
  onClick,
}: {
  row: Row<TData>
  index: number
  measure?: (el: Element | null) => void
  href?: string
  isOrigin: boolean
  mark?: ItemMark
  markLabel: Record<ItemMark, string>
  titleColumnId?: string
  onClick?: () => void
}) {
  return (
    <Zoom href={href} isOrigin={isOrigin}>
      <TableRow
        ref={measure}
        data-index={index}
        aria-rowindex={index + 2}
        data-state={row.getIsSelected() ? "selected" : undefined}
        data-mark={mark}
        onClick={
          onClick
            ? (e) => {
                if (!(e.target as HTMLElement).closest(interactive)) onClick()
              }
            : undefined
        }
        className={cn(onClick && "cursor-pointer", mark && markRow[mark])}
      >
        {row.getVisibleCells().map((cell) => (
          <TableCell
            key={cell.id}
            className="h-10 py-1.5 group-data-[density=compact]/table:h-8 group-data-[density=compact]/table:py-0.5"
          >
            {mark && cell.column.id === titleColumnId ? (
              <div className="flex flex-wrap items-center gap-x-2 gap-y-1">
                <div className="min-w-0">{flexRender(cell.column.columnDef.cell, cell.getContext())}</div>
                <RowMark mark={mark} label={markLabel} />
              </div>
            ) : (
              flexRender(cell.column.columnDef.cell, cell.getContext())
            )}
          </TableCell>
        ))}
      </TableRow>
    </Zoom>
  )
}

/** The card is a link (with `getRowHref`), a button (with `onRowClick`), or plain content. */
function CardWrapper({
  href,
  isOrigin,
  onClick,
  labelledBy,
  className,
  children,
}: {
  href?: string
  isOrigin: boolean
  onClick?: () => void
  labelledBy?: string
  className: string
  children: React.ReactNode
}) {
  if (href)
    return (
      <Zoom href={href} isOrigin={isOrigin}>
        <Link href={href} aria-labelledby={labelledBy} className={className}>
          {children}
        </Link>
      </Zoom>
    )
  if (onClick)
    return (
      <button type="button" onClick={onClick} aria-labelledby={labelledBy} className={className}>
        {children}
      </button>
    )
  return <div className={className}>{children}</div>
}

function DataCard<TData>({
  cells,
  index,
  setSize,
  measure,
  slotOf,
  mark,
  markLabel,
  href,
  isOrigin,
  onClick,
}: {
  cells: Cell<TData, unknown>[]
  index: number
  setSize: number
  measure?: (el: Element | null) => void
  slotOf: (cell: Cell<TData, unknown>) => CardSlot | undefined
  mark?: ItemMark
  markLabel: Record<ItemMark, string>
  href?: string
  isOrigin: boolean
  onClick?: () => void
}) {
  const titleId = React.useId()
  const slot = (name: CardSlot) => {
    const content = cells.filter((c) => slotOf(c) === name).map((c) => (
      <React.Fragment key={c.id}>{flexRender(c.column.columnDef.cell, c.getContext())}</React.Fragment>
    ))
    return content.length ? content : null
  }
  const title = slot("title")
  const status = slot("status")
  const subtitle = slot("subtitle")
  const value = slot("value")

  return (
    <li
      ref={measure}
      data-index={index}
      aria-setsize={setSize}
      aria-posinset={index + 1}
      data-mark={mark}
      className={cn("border-b last:border-b-0", mark && markRow[mark])}
    >
      <CardCellContext.Provider value>
        <CardWrapper
          href={href}
          isOrigin={isOrigin}
          onClick={onClick}
          labelledBy={title ? titleId : undefined}
          className="flex min-h-11 w-full flex-col gap-1 px-4 py-3 text-left outline-none hover:bg-muted/50 focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset"
        >
          {title || status ? (
            <span className="flex items-start justify-between gap-3">
              {title ? (
                <span id={titleId} data-slot="card-title" className="min-w-0 font-medium">
                  {title}
                  {mark ? (
                    <>
                      {" "}
                      <RowMark mark={mark} label={markLabel} />
                    </>
                  ) : null}
                </span>
              ) : (
                <span />
              )}
              {status ? (
                <span data-slot="card-status" className="shrink-0">
                  {status}
                </span>
              ) : null}
            </span>
          ) : null}
          {subtitle || value ? (
            <span className="flex items-baseline justify-between gap-3 text-muted-foreground">
              {subtitle ? (
                <span data-slot="card-subtitle" className="flex min-w-0 flex-wrap items-center gap-x-2">
                  {subtitle}
                </span>
              ) : (
                <span />
              )}
              {value ? (
                <span data-slot="card-value" className="shrink-0 text-foreground tabular-nums">
                  {value}
                </span>
              ) : null}
            </span>
          ) : null}
        </CardWrapper>
      </CardCellContext.Provider>
    </li>
  )
}

"use client"

import * as React from "react"

/** What the server filters, searches and sorts by. The same shape lives in the URL. */
export type ListQuery = {
  q?: string
  /** Selected values per column id. */
  filters: Record<string, string[]>
  sort?: { id: string; desc: boolean }
}

/** Counts per option, per column id, for the Filters. */
export type ListFacets = Record<string, Record<string, number>>

export type ListPage<TData> = {
  items: TData[]
  /** `null` when there is nothing after this page. */
  nextCursor: string | null
  /** Every record that matches the query, not only the loaded ones. */
  total: number
  facets?: ListFacets
}

/** Fetches one page; `cursor` is `null` for the first page. */
export type FetchPage<TData> = (args: { cursor: string | null; query: ListQuery }) => Promise<ListPage<TData>>

/** Fetches one record again; `matches` says whether it still matches `query`. `null` means it was deleted. */
export type FetchItem<TData> = (id: string, query: ListQuery) => Promise<{ item: TData; matches: boolean } | null>

export const emptyQuery: ListQuery = { filters: {} }

/** Stable string for a query: same filters in any order give the same key. */
export function queryKey(query: ListQuery): string {
  const filters = Object.keys(query.filters)
    .filter((k) => query.filters[k]?.length)
    .sort()
    .map((k) => `${k}=${[...query.filters[k]].sort().join(",")}`)
  return JSON.stringify([query.q ?? "", filters, query.sort ? `${query.sort.id}.${query.sort.desc ? "desc" : "asc"}` : ""])
}

export type ListStatus =
  /** First page in flight and nothing to show yet. */
  | "loading"
  /** The query changed: the rows on screen are from the previous query. */
  | "refreshing"
  | "loading-more"
  | "error"
  | "idle"

/**
 * How a record changed since its page loaded: created here (`new`), edited so it no longer matches the
 * query (`stale`), or `deleted`. Marks stay until the next search, filter or sort.
 */
export type ItemMark = "new" | "stale" | "deleted"

export type InfiniteListState<TData> = {
  items: TData[]
  marks: Record<string, ItemMark>
  nextCursor: string | null
  total: number
  facets?: ListFacets
  status: ListStatus
  /** Key of the query the items belong to. */
  key: string
}

/**
 * Loads pages of `fetchPage` one after another. When `query` changes, the pages start over:
 * the old rows stay (status `refreshing`) until the first page of the new query arrives.
 */
export function useInfiniteList<TData>(
  fetchPage: FetchPage<TData> | undefined,
  query: ListQuery,
  initial?: InfiniteListState<TData>,
  /** Pages kept for a query key (the list cache), used instead of fetching when the key changes. */
  restore?: (key: string) => InfiniteListState<TData> | null | undefined,
) {
  const key = queryKey(query)
  const [state, setState] = React.useState<InfiniteListState<TData>>(
    () =>
      initial ?? { items: [], marks: {}, nextCursor: null, total: 0, status: fetchPage ? "loading" : "idle", key: "" },
  )
  // Every request carries a token; a response whose token is stale is dropped.
  const token = React.useRef(0)
  const queryRef = React.useRef(query)
  const fetchRef = React.useRef(fetchPage)
  const stateRef = React.useRef(state)
  const restoreRef = React.useRef(restore)
  React.useLayoutEffect(() => {
    queryRef.current = query
    fetchRef.current = fetchPage
    stateRef.current = state
    restoreRef.current = restore
  })

  const load = React.useCallback((cursor: string | null, forKey: string) => {
    const fetcher = fetchRef.current
    if (!fetcher) return
    const mine = ++token.current
    setState((s) => ({
      ...s,
      status: cursor ? "loading-more" : s.items.length ? "refreshing" : "loading",
    }))
    fetcher({ cursor, query: queryRef.current }).then(
      (page) => {
        if (mine !== token.current) return
        setState((s) => ({
          items: cursor ? [...s.items, ...page.items] : page.items,
          marks: cursor ? s.marks : {},
          nextCursor: page.nextCursor,
          total: page.total,
          facets: page.facets ?? (cursor ? s.facets : undefined),
          status: "idle",
          key: forKey,
        }))
      },
      () => {
        if (mine !== token.current) return
        setState((s) => ({ ...s, status: "error" }))
      },
    )
  }, [])

  // A new query (or the first render without data for it) starts over from the first page.
  React.useEffect(() => {
    if (!fetchRef.current || state.key === key) return
    const cached = restoreRef.current?.(key)
    if (cached) {
      token.current++
      setState(cached)
      return
    }
    load(null, key)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key, load])

  const fetchNext = React.useCallback(() => {
    const s = stateRef.current
    if (s.status !== "idle" || !s.nextCursor) return
    stateRef.current = { ...s, status: "loading-more" }
    load(s.nextCursor, s.key)
  }, [load])

  /** After an error: repeats the request that failed. */
  const retry = React.useCallback(() => {
    const s = stateRef.current
    if (s.status !== "error") return
    load(s.key === key && s.items.length ? s.nextCursor : null, key)
  }, [key, load])

  /** Starts over from the first page, dropping what is loaded. */
  const reload = React.useCallback(() => {
    setState((s) => ({ ...s, items: [], marks: {}, nextCursor: null, total: 0, facets: undefined }))
    load(null, key)
  }, [key, load])

  return { ...state, fetchNext, retry, reload, setState }
}

/**
 * Applies a record fetched again to the loaded pages: replaced in place (marked `stale` when it no
 * longer matches), marked `deleted` when gone, or added on top as `new` when created and matching.
 */
export function applyItemUpdate<TData>(
  state: InfiniteListState<TData>,
  update: { id: string; kind: "changed" | "created" },
  result: { item: TData; matches: boolean } | null,
  idOf: (item: TData) => string,
): InfiniteListState<TData> {
  const index = state.items.findIndex((item) => idOf(item) === update.id)
  const marks = { ...state.marks }
  if (update.kind === "created") {
    if (!result || !result.matches || index >= 0) return state
    marks[update.id] = "new"
    return { ...state, items: [result.item, ...state.items], total: state.total + 1, marks }
  }
  if (index < 0) return state
  if (!result) {
    marks[update.id] = "deleted"
    return { ...state, marks }
  }
  const items = state.items.slice()
  items[index] = result.item
  if (!result.matches) marks[update.id] = "stale"
  else if (marks[update.id] !== "new") delete marks[update.id]
  return { ...state, items, marks }
}

"use client"

import { usePathname, useRouter, useSearchParams } from "next/navigation"
import * as React from "react"

import { type ListQuery, queryKey } from "@/components/data-table/list-source"

/**
 * The URL is the only source of a list's search, filters and sort:
 * `q=<text>`, one `<columnId>=<value>,<value>` per filtered column, and `sort=<columnId>.asc|desc`.
 */
export function parseListQuery(params: URLSearchParams, columnIds: readonly string[]): ListQuery {
  const filters: Record<string, string[]> = {}
  for (const id of columnIds) {
    const raw = params.get(id)
    if (raw) filters[id] = raw.split(",").filter(Boolean)
  }
  const sortRaw = params.get("sort")
  const match = sortRaw?.match(/^(.+)\.(asc|desc)$/)
  return {
    q: params.get("q") || undefined,
    filters,
    sort: match && columnIds.includes(match[1]) ? { id: match[1], desc: match[2] === "desc" } : undefined,
  }
}

/** Writes `query` over `params`, keeping parameters that are not the list's. */
export function writeListQuery(params: URLSearchParams, query: ListQuery, columnIds: readonly string[]) {
  const next = new URLSearchParams(params)
  for (const id of [...columnIds, "q", "sort"]) next.delete(id)
  if (query.q) next.set("q", query.q)
  for (const [id, values] of Object.entries(query.filters)) if (values.length) next.set(id, values.join(","))
  if (query.sort) next.set("sort", `${query.sort.id}.${query.sort.desc ? "desc" : "asc"}`)
  return next
}

/**
 * The list's query, read from and written to the URL with `router.replace` (no new history entries).
 * Only the list's own path counts: while a Dialog roteado is open the URL is the dialog's, and the list
 * keeps its query.
 */
export function useUrlListQuery(columnIds: readonly string[]) {
  const router = useRouter()
  const pathname = usePathname()
  const [listPath] = React.useState(pathname)
  const searchParams = useSearchParams()
  const idsKey = columnIds.join("|")
  const fromUrl = React.useMemo(
    () => parseListQuery(new URLSearchParams(searchParams.toString()), idsKey.split("|")),
    [searchParams, idsKey],
  )
  // A local copy answers at once; the URL catches up after `router.replace`.
  const [query, setLocal] = React.useState(fromUrl)
  // Key of the last URL this hook took in, and the keys of our own replaces still on their way.
  const [seen, setSeen] = React.useState(queryKey(fromUrl))
  const [pending, setPending] = React.useState<string[]>([])
  const urlKey = queryKey(fromUrl)
  if (pathname === listPath && urlKey !== seen) {
    setSeen(urlKey)
    const mine = pending.indexOf(urlKey)
    if (mine >= 0) {
      // One of our own replaces landed; a later one may still be on its way.
      setPending(pending.slice(mine + 1))
    } else {
      // The URL changed from outside (back, a link): it wins.
      setPending([])
      setLocal(fromUrl)
    }
  }

  const queryRef = React.useRef(query)
  React.useLayoutEffect(() => {
    queryRef.current = query
  })

  const setQuery = React.useCallback(
    (update: (q: ListQuery) => ListQuery) => {
      const next = update(queryRef.current)
      if (queryKey(next) === queryKey(queryRef.current)) return
      queryRef.current = next
      setLocal(next)
      setPending((p) => [...p, queryKey(next)])
      const params = writeListQuery(new URLSearchParams(window.location.search), next, idsKey.split("|")).toString()
      router.replace(params ? `${listPath}?${params}` : listPath, { scroll: false })
    },
    [router, listPath, idsKey],
  )

  return [query, setQuery] as const
}

"use client"

import { isRoutedDialogOpen, type RoutedDialogEventDetail, routedDialogEvent } from "@/lib/routed"

/** A record that changed somewhere else (a Dialog roteado, an action), to be fetched again by the lists that show it. */
export type ItemUpdate = { resource: string; id: string; kind: "changed" | "created" }

const queue: ItemUpdate[] = []
const listeners = new Set<(updates: ItemUpdate[]) => void>()
let listening = false

function flush() {
  if (!queue.length) return
  const updates = queue.splice(0)
  for (const listener of listeners) listener(updates)
}

function schedule() {
  if (!listening) {
    listening = true
    window.addEventListener(routedDialogEvent, (e) => {
      if ((e as CustomEvent<RoutedDialogEventDetail>).detail.type === "close") flush()
    })
  }
  // With a Dialog roteado open, the list behind waits until it closes, so nothing moves under the user.
  if (!isRoutedDialogOpen()) queueMicrotask(flush)
}

/**
 * Tells every list of `resource` that a record changed (edited, deleted). When the Dialog roteado
 * closes, they fetch that record again with `fetchItem` and update it in place.
 */
export function markItemChanged(resource: string, id: string) {
  queue.push({ resource, id, kind: "changed" })
  schedule()
}

/** Tells every list of `resource` that a record was created: it shows on top, marked as new, if it matches. */
export function markItemCreated(resource: string, id: string) {
  queue.push({ resource, id, kind: "created" })
  schedule()
}

/** For `DataTable`: called with the updates when they are due. */
export function subscribeItemUpdates(listener: (updates: ItemUpdate[]) => void) {
  listeners.add(listener)
  return () => {
    listeners.delete(listener)
  }
}

"use client"

import { type FetchItem, type InfiniteListState, type ListQuery, applyItemUpdate, queryKey } from "@/components/data-table/list-source"
import { subscribeItemUpdates } from "@/components/data-table/list-updates"

/** Where the list was on screen: the first visible record and how far its top was from the top of the viewport. */
export type ListPosition = { index: number; offset: number }

type Entry = {
  /** `null` when the list had more records than the cache keeps: only the position is restored. */
  state: InfiniteListState<unknown> | null
  position: ListPosition | null
  savedAt: number
  resource?: string
  query: ListQuery
  fetchItem?: FetchItem<unknown>
  idOf: (item: unknown) => string
}

/** The session cache keeps few lists, for a short time, and only so many records each. */
export const listCacheLimits = { lists: 5, maxAgeMs: 10 * 60 * 1000, maxItems: 1000 }

// Map keeps insertion order: the first entry is the least recently left.
const entries = new Map<string, Entry>()
let subscribed = false

/** The cache key of a list: its path and its query. */
export function listCacheKey(path: string, query: ListQuery) {
  return `${path}?${queryKey(query)}`
}

/** A list leaving the screen (the sidebar, a link) keeps its pages, marks and position here. */
export function saveList<TData>(
  key: string,
  entry: {
    state: InfiniteListState<TData>
    position: ListPosition | null
    resource?: string
    query: ListQuery
    fetchItem?: FetchItem<TData>
    idOf: (item: TData) => string
  },
) {
  if (!subscribed) {
    subscribed = true
    // Records changed while their list is away are fetched again and updated in the cache too.
    subscribeItemUpdates(async (updates) => {
      for (const update of updates) {
        for (const cached of entries.values()) {
          if (!cached.state || cached.resource !== update.resource || !cached.fetchItem) continue
          const result = await cached.fetchItem(update.id, cached.query).catch(() => undefined)
          if (result === undefined || !cached.state) continue
          cached.state = applyItemUpdate(cached.state, update, result, cached.idOf)
        }
      }
    })
  }
  const { state } = entry
  const keep = state.items.length <= listCacheLimits.maxItems
  entries.delete(key)
  entries.set(key, {
    state: keep ? { ...(state as InfiniteListState<unknown>), status: "idle" } : null,
    position: entry.position,
    savedAt: Date.now(),
    resource: entry.resource,
    query: entry.query,
    fetchItem: entry.fetchItem as FetchItem<unknown> | undefined,
    idOf: entry.idOf as (item: unknown) => string,
  })
  while (entries.size > listCacheLimits.lists) entries.delete(entries.keys().next().value!)
}

/** Takes a list back out of the cache when it mounts again; nothing when it is missing or too old. */
export function takeList<TData>(key: string) {
  const entry = entries.get(key)
  entries.delete(key)
  if (!entry || Date.now() - entry.savedAt > listCacheLimits.maxAgeMs) return undefined
  return { state: entry.state as InfiniteListState<TData> | null, position: entry.position }
}

"use client"

import type { Column } from "@tanstack/react-table"
import { ArrowDown, ArrowUp, ChevronsUpDown } from "lucide-react"

import { cn } from "@/lib/utils"

export function ColumnHeader<TData, TValue>({
  column,
  title,
  align = "left",
}: {
  column: Column<TData, TValue>
  title: string
  align?: "left" | "right"
}) {
  if (!column.getCanSort()) return <span className={cn(align === "right" && "block text-right")}>{title}</span>
  const sorted = column.getIsSorted()
  const Icon = sorted === "asc" ? ArrowUp : sorted === "desc" ? ArrowDown : ChevronsUpDown

  return (
    <button
      type="button"
      data-slot="column-header"
      onClick={column.getToggleSortingHandler()}
      className={cn(
        "-mx-1.5 inline-flex h-7 items-center gap-1 rounded-md px-1.5 hover:bg-muted hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none",
        align === "right" && "ml-auto flex flex-row-reverse",
      )}
    >
      {title}
      <Icon aria-hidden className={cn("size-3.5", !sorted && "opacity-50")} />
    </button>
  )
}

"use client"

import type { Column } from "@tanstack/react-table"
import { Check, PlusCircle } from "lucide-react"

import { Button } from "@/components/ui/button"
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandSeparator,
} from "@/components/ui/command"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import { Separator } from "@/components/ui/separator"
import { mergeLabels } from "@/lib/labels"
import { cn } from "@/lib/utils"

type Option = { label: string; value: string }

export type FacetedFilterLabels = {
  /** Shown on the chip when more than two options are selected. */
  selected: (count: number) => string
  noResults: string
  clear: string
}

export const defaultFacetedFilterLabels: FacetedFilterLabels = {
  selected: (count) => `${count} selected`,
  noResults: "No results found.",
  clear: "Clear filter",
}

/** `filterFn` for columns used with `FacetedFilter` and the toolbar's Filters panel: the row matches any selected value. */
export const multiValueFilter = (row: { getValue: (id: string) => unknown }, id: string, value: string[]) =>
  value.includes(row.getValue(id) as string)

/** Stripe-style filter chip: multi-select with live counts per option. */
export function FacetedFilter<TData, TValue>({
  column,
  title,
  options,
  labels,
}: {
  column?: Column<TData, TValue>
  title: string
  options: Option[]
  /** Partial overrides, merged over `defaultFacetedFilterLabels`. */
  labels?: Partial<FacetedFilterLabels>
}) {
  const t = mergeLabels(defaultFacetedFilterLabels, labels)
  const facets = column?.getFacetedUniqueValues()
  const selected = new Set((column?.getFilterValue() as string[] | undefined) ?? [])

  const toggle = (value: string) => {
    const next = new Set(selected)
    if (next.has(value)) next.delete(value)
    else next.add(value)
    column?.setFilterValue(next.size ? Array.from(next) : undefined)
  }

  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button variant="outline" className="border-dashed">
          <PlusCircle aria-hidden />
          {title}
          {selected.size > 0 ? (
            <>
              <Separator orientation="vertical" className="mx-0.5 data-[orientation=vertical]:h-4" />
              <span className="rounded bg-secondary px-1.5 text-xs font-medium">
                {selected.size > 2
                  ? t.selected(selected.size)
                  : options
                      .filter((o) => selected.has(o.value))
                      .map((o) => o.label)
                      .join(", ")}
              </span>
            </>
          ) : null}
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-56 p-0" align="start">
        <Command>
          <CommandInput placeholder={title} />
          <CommandList>
            <CommandEmpty>{t.noResults}</CommandEmpty>
            <CommandGroup>
              {options.map((o) => {
                const isSelected = selected.has(o.value)
                return (
                  <CommandItem key={o.value} onSelect={() => toggle(o.value)} aria-selected={isSelected}>
                    <span
                      aria-hidden
                      className={cn(
                        "flex size-4 items-center justify-center rounded-[4px] border",
                        isSelected ? "border-primary bg-primary text-primary-foreground" : "border-input",
                      )}
                    >
                      {isSelected ? <Check className="size-3" /> : null}
                    </span>
                    <span className="flex-1">{o.label}</span>
                    {facets?.size ? (
                      <span className="font-mono text-xs text-muted-foreground tabular-nums">
                        {facets.get(o.value) ?? 0}
                      </span>
                    ) : null}
                  </CommandItem>
                )
              })}
            </CommandGroup>
            {selected.size > 0 ? (
              <>
                <CommandSeparator />
                <CommandGroup>
                  <CommandItem onSelect={() => column?.setFilterValue(undefined)} className="justify-center">
                    {t.clear}
                  </CommandItem>
                </CommandGroup>
              </>
            ) : null}
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  )
}

"use client"

import type { Column, Table } from "@tanstack/react-table"
import { Columns3, Rows3, Rows4, Search, SlidersHorizontal, X } from "lucide-react"
import * as React from "react"

import type { Density } from "@/components/data-table/data-table"
import { FacetedFilter, type FacetedFilterLabels } from "@/components/data-table/faceted-filter"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuLabel,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import { Sheet, SheetContent, SheetFooter, SheetHeader, SheetTitle, SheetTrigger } from "@/components/ui/sheet"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"
import { mergeLabels } from "@/lib/labels"

export type DataTableToolbarLabels = {
  /** Title of the panel and of the button that opens it on the Celular. */
  filters: string
  /** Text of the button that opens the panel; `active` is the number of facets with a filter. */
  filtersButton: (active: number) => string
  /** Clears the search and the filters from the toolbar (from md up). */
  reset: string
  /** Clears the filters and the sort from the panel. */
  clear: string
  /** Primary button in the panel footer; `count` is the number of matching rows. */
  showResults: (count: number) => string
  sortBy: string
  ascending: string
  descending: string
  density: string
  comfortable: string
  compact: string
  columns: string
  toggleColumns: string
}

export const defaultDataTableToolbarLabels: DataTableToolbarLabels = {
  filters: "Filters",
  filtersButton: (active) => (active > 0 ? `Filters (${active})` : "Filters"),
  reset: "Reset",
  clear: "Clear",
  showResults: (count) => `View ${count.toLocaleString("en-US")} ${count === 1 ? "result" : "results"}`,
  sortBy: "Sort by",
  ascending: "Ascending",
  descending: "Descending",
  density: "Row density",
  comfortable: "Comfortable rows",
  compact: "Compact rows",
  columns: "Columns",
  toggleColumns: "Toggle columns",
}

export type FacetFilter = {
  /** Column id. */
  column: string
  title: string
  options: { label: string; value: string }[]
}

type DataTableToolbarProps<TData> = {
  table: Table<TData>
  density: Density
  onDensityChange: (density: Density) => void
  search: { label: string; placeholder?: string }
  filters?: FacetFilter[]
  /** Column ids offered in "Sort by". Defaults to every column that can be sorted. */
  sortColumns?: string[]
  /** Partial overrides, merged over `defaultDataTableToolbarLabels`. */
  labels?: Partial<DataTableToolbarLabels>
  /** Partial overrides for the filter chips. */
  filterLabels?: Partial<FacetedFilterLabels>
}

const searchDelay = 300

/** The search box text, applied to the table's global filter 300ms after the last keystroke. */
function useDebouncedSearch<TData>(table: Table<TData>) {
  const applied = (table.getState().globalFilter as string | undefined) ?? ""
  const [text, setText] = React.useState(applied)
  const [lastApplied, setLastApplied] = React.useState(applied)
  const timer = React.useRef<ReturnType<typeof setTimeout>>(undefined)
  // The filter changed from outside (Reset, the URL): show it.
  if (applied !== lastApplied) {
    setLastApplied(applied)
    setText(applied)
  }
  React.useEffect(() => () => clearTimeout(timer.current), [])
  const update = (value: string, { now = false }: { now?: boolean } = {}) => {
    setText(value)
    clearTimeout(timer.current)
    if (now) table.setGlobalFilter(value)
    else timer.current = setTimeout(() => table.setGlobalFilter(value), searchDelay)
  }
  return [text, update] as const
}

/** Title of a column in menus: `meta.title`, else a plain-string header, else the id. */
function columnTitle<TData>(column: Column<TData, unknown>) {
  const header = column.columnDef.header
  return column.columnDef.meta?.title ?? (typeof header === "string" ? header : column.id)
}

export function DataTableToolbar<TData>({
  table,
  density,
  onDensityChange,
  search,
  filters = [],
  sortColumns,
  labels,
  filterLabels,
}: DataTableToolbarProps<TData>) {
  const t = mergeLabels(defaultDataTableToolbarLabels, labels)
  const [open, setOpen] = React.useState(false)
  const state = table.getState()
  const active = filters.filter((f) => {
    const value = table.getColumn(f.column)?.getFilterValue() as unknown[] | undefined
    return !!value?.length
  }).length
  const dirty = state.columnFilters.length > 0 || !!state.globalFilter
  const sortable = (
    sortColumns
      ? sortColumns.map((id) => table.getColumn(id))
      : table.getAllLeafColumns().filter((c) => c.accessorFn && c.getCanSort())
  ).filter((c): c is Column<TData, unknown> => !!c)
  const sort = state.sorting[0]
  const results = table.options.meta?.total ?? table.getFilteredRowModel().rows.length
  const [searchText, setSearchText] = useDebouncedSearch(table)

  return (
    <div className="flex flex-wrap items-center gap-2">
      <div className="relative min-w-0 flex-1 md:flex-none">
        <Search
          aria-hidden
          className="pointer-events-none absolute top-1/2 left-2.5 size-4 -translate-y-1/2 text-muted-foreground"
        />
        <Input
          type="search"
          aria-label={search.label}
          placeholder={search.placeholder}
          value={searchText}
          onChange={(e) => setSearchText(e.target.value)}
          className="w-full pl-8 md:w-56 lg:w-72"
        />
      </div>

      <Sheet open={open} onOpenChange={setOpen}>
        <SheetTrigger asChild>
          <Button variant="outline" className="md:hidden">
            <SlidersHorizontal aria-hidden />
            {t.filtersButton(active)}
          </Button>
        </SheetTrigger>
        <SheetContent
          side="bottom"
          showCloseButton={false}
          aria-describedby={undefined}
          className="max-h-[85dvh] gap-0 rounded-t-xl"
        >
          <SheetHeader className="border-b">
            <SheetTitle>{t.filters}</SheetTitle>
          </SheetHeader>
          <div className="flex flex-col gap-6 overflow-y-auto p-4">
            {filters.map((f) => (
              <FacetSection key={f.column} filter={f} column={table.getColumn(f.column)} />
            ))}
            {sortable.length ? (
              <fieldset className="flex flex-col gap-2">
                <legend className="mb-1 font-medium">{t.sortBy}</legend>
                <RadioGroup
                  aria-label={t.sortBy}
                  value={sort?.id ?? ""}
                  onValueChange={(id) => table.setSorting([{ id, desc: sort?.desc ?? false }])}
                >
                  {sortable.map((c) => (
                    <Label key={c.id} className="gap-3 py-2">
                      <RadioGroupItem value={c.id} />
                      {columnTitle(c)}
                    </Label>
                  ))}
                </RadioGroup>
                <RadioGroup
                  aria-label={`${t.sortBy}: ${t.ascending} / ${t.descending}`}
                  value={sort ? (sort.desc ? "desc" : "asc") : ""}
                  disabled={!sort}
                  onValueChange={(dir) => sort && table.setSorting([{ id: sort.id, desc: dir === "desc" }])}
                  className="grid-cols-2"
                >
                  <Label className="gap-3 py-2">
                    <RadioGroupItem value="asc" />
                    {t.ascending}
                  </Label>
                  <Label className="gap-3 py-2">
                    <RadioGroupItem value="desc" />
                    {t.descending}
                  </Label>
                </RadioGroup>
              </fieldset>
            ) : null}
          </div>
          <SheetFooter className="flex-row border-t pb-[calc(1rem+env(safe-area-inset-bottom))]">
            <Button
              variant="outline"
              onClick={() => {
                table.resetColumnFilters()
                table.resetSorting()
              }}
            >
              {t.clear}
            </Button>
            <Button className="flex-1" onClick={() => setOpen(false)}>
              {t.showResults(results)}
            </Button>
          </SheetFooter>
        </SheetContent>
      </Sheet>

      <div className="hidden items-center gap-2 md:contents">
        {filters.map((f) => (
          <FacetedFilter
            key={f.column}
            column={table.getColumn(f.column)}
            title={f.title}
            options={f.options}
            labels={filterLabels}
          />
        ))}
        {dirty ? (
          <Button
            variant="ghost"
            onClick={() => {
              table.resetColumnFilters()
              setSearchText("", { now: true })
            }}
          >
            {t.reset}
            <X aria-hidden />
          </Button>
        ) : null}
        <div className="ml-auto flex items-center gap-2">
          <ToggleGroup
            type="single"
            variant="outline"
            value={density}
            onValueChange={(v) => v && onDensityChange(v as Density)}
            aria-label={t.density}
          >
            <ToggleGroupItem value="comfortable" aria-label={t.comfortable}>
              <Rows3 />
            </ToggleGroupItem>
            <ToggleGroupItem value="compact" aria-label={t.compact}>
              <Rows4 />
            </ToggleGroupItem>
          </ToggleGroup>
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="outline">
                <Columns3 aria-hidden />
                {t.columns}
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-44">
              <DropdownMenuLabel className="text-xs text-muted-foreground">{t.toggleColumns}</DropdownMenuLabel>
              {table
                .getAllColumns()
                .filter((c) => c.getCanHide())
                .map((c) => (
                  <DropdownMenuCheckboxItem
                    key={c.id}
                    checked={c.getIsVisible()}
                    onCheckedChange={(v) => c.toggleVisibility(!!v)}
                  >
                    {columnTitle(c)}
                  </DropdownMenuCheckboxItem>
                ))}
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>
    </div>
  )
}

function FacetSection<TData>({ filter, column }: { filter: FacetFilter; column?: Column<TData, unknown> }) {
  const facets = column?.getFacetedUniqueValues()
  const selected = new Set((column?.getFilterValue() as string[] | undefined) ?? [])

  const toggle = (value: string, checked: boolean) => {
    const next = new Set(selected)
    if (checked) next.add(value)
    else next.delete(value)
    column?.setFilterValue(next.size ? Array.from(next) : undefined)
  }

  return (
    <fieldset className="flex flex-col gap-1">
      <legend className="mb-1 font-medium">{filter.title}</legend>
      {filter.options.map((o) => (
        <Label key={o.value} className="gap-3 py-2">
          <Checkbox checked={selected.has(o.value)} onCheckedChange={(v) => toggle(o.value, v === true)} />
          <span className="flex-1">{o.label}</span>
          {facets?.size ? (
            <span className="font-mono text-xs text-muted-foreground tabular-nums">{facets.get(o.value) ?? 0}</span>
          ) : null}
        </Label>
      ))}
    </fieldset>
  )
}

import { cn } from "@/lib/utils"

export type Tone = "neutral" | "info" | "warning" | "success" | "danger"

const tones: Record<Tone, string> = {
  neutral: "bg-muted text-foreground [--dot:var(--muted-foreground)]",
  info: "bg-info/10 text-info [--dot:var(--info)]",
  warning: "bg-warning/10 text-warning [--dot:var(--warning)]",
  success: "bg-success/10 text-success [--dot:var(--success)]",
  danger: "bg-destructive/10 text-destructive [--dot:var(--destructive)]",
}

/** Status pill: colour + dot + text, so meaning never depends on colour alone. */
export function StatusBadge({ tone, children, className }: { tone: Tone; children: React.ReactNode; className?: string }) {
  return (
    <span
      className={cn(
        "inline-flex h-6 items-center gap-1.5 rounded-md px-2 text-xs font-medium whitespace-nowrap",
        tones[tone],
        className,
      )}
    >
      <span aria-hidden className="size-1.5 rounded-full bg-(--dot)" />
      {children}
    </span>
  )
}

/** Merge partial label overrides over the defaults; an explicit `undefined` keeps the default. */
export function mergeLabels<T extends object>(defaults: T, overrides?: Partial<T>): T {
  const merged = { ...defaults }
  for (const key of Object.keys(overrides ?? {}) as (keyof T)[]) {
    const value = overrides?.[key]
    if (value !== undefined) merged[key] = value as T[keyof T]
  }
  return merged
}

/**
 * The contract between a list and the Dialog roteado opened from it. Shared by `@backoffice/data-table`
 * and `@backoffice/routed-dialog`, so neither block imports the other.
 */

/** Fired on `window` when a Dialog roteado opens or closes. */
export const routedDialogEvent = "backoffice:routed-dialog"

export type RoutedDialogEventDetail = {
  type: "open" | "close"
  /** Path the dialog was opened at, e.g. `/orders/ORD-1`: the href of the row or card it came from. */
  origin: string
}

export function dispatchRoutedDialogEvent(detail: RoutedDialogEventDetail) {
  window.dispatchEvent(new CustomEvent<RoutedDialogEventDetail>(routedDialogEvent, { detail }))
}

/** True while a Dialog roteado is on screen. */
export function isRoutedDialogOpen() {
  return typeof document !== "undefined" && !!document.querySelector("[data-slot='routed-dialog']")
}

/** View Transition name shared by a row or card and the dialog opened from it. */
export function routedTransitionName(href: string) {
  return `routed-${href.replace(/[^a-zA-Z0-9_-]/g, "_")}`
}
